python3 -c "
import json
with open('/home/mike-anderson/vaults/cohezion-vault/.claude/settings.local.json') as f:
    data = json.load(f)
allow = data['permissions']['allow']

# Categorize rules
categories = {}
for rule in allow:
    if rule.startswith('Bash('):
        # Extract command prefix
        inner = rule[5:]  # Remove 'Bash('
        if ':' in inner[:30]:
            prefix = inner.split(':')[0]
        elif ' ' in inner[:50]:
            prefix = inner.split(' ')[0]
        else:
            prefix = inner[:30]
        categories.setdefault(prefix, []).append(len(rule))
    else:
        categories.setdefault('non-bash', []).append(len(rule))

for cat, lengths in sorted(categories.items(), key=lambda x: -len(x[1])):
    print(f'{cat}: {len(lengths)} rules, avg len={sum(lengths)//len(lengths)}, max={max(lengths)}')
"
